// Golden-value tests of the Site (chantier) rules (src/domain/site.ts) against the prototype's own render values
// (src/domain/site.golden.json, generated by scripts/proto-golden-site.ts from logic 4739–4760 in node:vm): the
// "Go chantier" rule and its five conditions, the KPI tiles of the three tabs, the status tags, the collision targets
// — on the prototype's data (SITE_* constants), at seed and after the transitions the screen offers. Plus the J-15
// late rule, the Go verdict once every condition is met (never reachable in the prototype: its collisions are a
// constant) and the Daily report form.
import { describe, expect, it } from 'vitest';
import PROTO from '@/server/prototype/prototype-data.json';
import { parseDateInput } from '@/domain/contract';
import {
  confirmStatus, cursusVerdict, equipmentSource, hseStatus, isoOfDisplayDate, punchOwnerParty, type ConfirmStatus, type HseStatus,
} from '@/server/db/codes';
import GOLDEN from './site.golden.json';
import {
  COLLISION_TARGET, collisionTagClass, equipmentSourceTagClass, execKpis, goChantier, goLabel, isPrerequisiteLate, manDaysConsumed, parseDailyReportForm,
  preparationNote, prerequisiteStep, readinessKpis, siteBadge, siteTabOf, siteTagClass, teamKpis, type SiteFacts, type SiteKpi,
} from './site';

/* eslint-disable @typescript-eslint/no-explicit-any */
const G = GOLDEN as any;
const P = PROTO as any;
const LO = 'var(--color-accent-300)';
const OK = 'var(--color-text)';
const iso = (d: string) => isoOfDisplayDate(d)!;

/** The prototype's site data as the DAL returns it, with optional status overrides (siteOv / siteEqOv). */
function facts(ov: { pre?: Record<number, ConfirmStatus>; eq?: Record<number, ConfirmStatus> } = {}): SiteFacts {
  const prerequisites = (P.SITE_PREREQ as string[][]).map(([, , due, st], i) => {
    const status = ov.pre?.[i] ?? confirmStatus.code(st);
    return { status, neededBy: iso(due), late: isPrerequisiteLate({ status, neededBy: iso(due) }) };
  });
  return {
    // A-12 (chapter 4): man-days planned and client decisions are inputs the DAL computes (rotation × calendar, change
    // requests with a decided client step); the prototype's figures are passed here so the tiles stay compared.
    startOn: iso(P.SITE.start), planDays: P.SITE.planDays, doneDays: P.SITE.doneDays, manDaysPlanned: 168, clientDecisions: 3,
    prerequisites,
    people: (P.SITE_DOCS as string[][]).map((d) => ({ verdict: cursusVerdict.code(d[5]) })),
    equipment: (P.SITE_EQUIP as string[][]).map(([, src, st], i) => ({ status: ov.eq?.[i] ?? confirmStatus.code(st), source: equipmentSource.code(src) })),
    collisions: (P.SITE_COLLISIONS as string[][]).map(() => ({ resolved: false })),
    rotation: (P.SITE_ROTATION as string[][]).map((r) => ({ rotationNo: +r[6] })),
    missionCosts: (P.SITE_COSTS as [string, number, number][]).map(([, b, a]) => ({ budgetKeur: b, actualKeur: a })),
    reports: (P.SITE_REPORTS as string[][]).map((r) => ({ reportOn: iso(r[0]), headcount: null, hseIncident: null })),
    punch: (P.SITE_PUNCH as string[][]).map((r) => ({ open: r[3] === 'Open', ownerParty: punchOwnerParty.code(r[4]) })),
    hse: (P.SITE_HSE as string[][]).map((h) => ({ status: (hseStatus.labels.includes(h[1]) ? hseStatus.code(h[1]) : 'recorded') as HseStatus })),
  };
}
const goOf = (f: SiteFacts) => goChantier({ prerequisites: f.prerequisites, people: f.people, equipment: f.equipment, collisions: f.collisions, hse: f.hse });
const kpi = (k: SiteKpi) => ({ label: k.label, value: k.value, sub: k.sub, color: k.alert ? LO : OK });
const golden = (ks: any[]) => ks.map((k) => ({ label: k.label, value: String(k.value), sub: k.sub, color: k.color }));

describe('Go chantier and the KPI tiles vs the prototype (EN)', () => {
  const scenarios: [string, any, Parameters<typeof facts>[0]][] = [
    ['seed', G.seed.en, {}],
    ['Client confirms on prerequisite 3', G.scenarios.confirmPrereq3.en, { pre: { 3: 'confirmed' } }],
    ['Signed on site on prerequisite 1', G.scenarios.signPrereq1.en, { pre: { 1: 'signed' } }],
    ['Confirm on equipment 2', G.scenarios.confirmEquip2.en, { eq: { 2: 'confirmed' } }],
    ['every prerequisite and equipment line confirmed', G.scenarios.allConfirmed.en, { pre: { 3: 'confirmed', 4: 'confirmed' }, eq: { 2: 'confirmed', 4: 'confirmed' } }],
  ];
  it.each(scenarios)('%s: Go conditions, label, readiness / team / execution tiles', (_, g, ov) => {
    const f = facts(ov);
    const go = goOf(f);
    expect(go.conditions.map((c) => ({ label: c.label, ok: c.ok, sub: c.sub, icon: c.ok ? 'ph ph-check-circle' : 'ph ph-warning-circle', color: LO }))).toEqual(g.goItems);
    expect(goLabel(go.ok)).toBe(g.goLabel);
    expect(readinessKpis(f, go).map(kpi)).toEqual(golden(g.kpis));
    expect(teamKpis(f, 'en').map(kpi)).toEqual(golden(g.teamKpis));
    expect(execKpis(f).map(kpi)).toEqual(golden(g.execKpis));
  });

  it('FR money in the Mission budget tile (the prototype formats with the language before translating)', () => {
    const k = teamKpis(facts(), 'fr')[3];
    expect([k.value, k.sub]).toEqual(['98 k€', '11 k€ committed · 11%']);
    expect(G.seed.fr.teamKpis[3]).toMatchObject({ value: '98 k€', sub: '11 k€ engagés · 11%' });
  });

  it('the sidebar badge: "NO GO" while Go chantier is not reached', () => {
    expect(siteBadge(goOf(facts()))).toBe(G.seed.en.badge);
    for (const s of Object.values(G.scenarios) as any[]) expect(siteBadge(goOf(facts()))).toBe(s.en.badge);
  });

  it('GO once every condition is met (no pending prerequisite, no Cursus NO GO, equipment confirmed, collisions resolved, no HSE pending)', () => {
    const f = facts({ pre: { 3: 'signed', 4: 'confirmed' }, eq: { 2: 'confirmed', 4: 'confirmed' } });
    const ready = goChantier({
      prerequisites: f.prerequisites, people: f.people.map((p) => ({ verdict: p.verdict === 'no_go' ? ('go_with_reserve' as const) : p.verdict })), equipment: f.equipment,
      collisions: f.collisions.map(() => ({ resolved: true })), hse: f.hse.map((h) => ({ status: h.status === 'pending' ? ('signed' as const) : h.status })),
    });
    expect(ready.ok).toBe(true);
    expect(ready.conditions.map((c) => [c.key, c.ok, c.sub, c.open])).toEqual([
      ['prerequisites', true, 'Ready', 0], ['cursus', true, 'Ready', 0], ['equipment', true, 'Ready', 0], ['collisions', true, 'Ready', 0], ['hse', true, 'Ready', 0],
    ]);
    expect([goLabel(ready.ok), siteBadge(ready), siteTagClass(goLabel(ready.ok))]).toEqual(['GO', '', 'tag tag-neutral']);
    // A GO with reserve does not block (only NO GO does); one resolved collision out of two still blocks.
    const one = goChantier({ ...ready, prerequisites: f.prerequisites.map((p) => ({ status: p.status === 'pending' ? 'signed' : p.status })), people: [{ verdict: 'go_with_reserve' }], equipment: f.equipment, collisions: [{ resolved: true }, { resolved: false }], hse: [] });
    expect(one.conditions.find((c) => c.key === 'collisions')).toMatchObject({ ok: false, sub: '1 collision', open: 1 });
  });
});

describe('status tags, steps and targets vs the prototype', () => {
  it('stTag on every status the screen shows (prerequisites, equipment, Cursus, punch, HSE), the source and kind tags', () => {
    const g = G.seed.en;
    for (const r of g.prereqs) expect(siteTagClass(r.status)).toBe(r.tagClass);
    for (const r of g.equip) expect([siteTagClass(r.status), equipmentSourceTagClass(equipmentSource.code(r.src))]).toEqual([r.tagClass, r.srcClass]);
    for (const r of g.docs) expect([siteTagClass(r.visa), siteTagClass(r.vacc), siteTagClass(r.hab), siteTagClass(r.status)]).toEqual([r.visaClass, r.vaccClass, r.habClass, r.tagClass]);
    for (const r of g.punch) expect(siteTagClass(r.status)).toBe(r.tagClass);
    for (const r of g.hse) expect(siteTagClass(r.status)).toBe(r.tagClass);
    const kinds: Record<string, 'load' | 'cert' | 'doc' | 'leave'> = { Load: 'load', Certificate: 'cert', Document: 'doc', Leave: 'leave' };
    for (const c of g.collisions) expect(collisionTagClass(kinds[c.kind])).toBe(c.tagClass);
  });

  it('prerequisite steps (canConfirm / canSign) and equipment Confirm follow the status, also after a transition', () => {
    for (const g of [G.seed.en, G.scenarios.confirmPrereq3.en, G.scenarios.signPrereq1.en]) {
      for (const r of g.prereqs) {
        const step = prerequisiteStep(confirmStatus.code(r.status));
        expect([step?.to === 'confirmed', step?.to === 'signed']).toEqual([r.canConfirm, r.canSign]);
      }
    }
    expect(prerequisiteStep('pending')).toEqual({ to: 'confirmed', label: 'Client confirms' });
    expect(prerequisiteStep('confirmed')).toEqual({ to: 'signed', label: 'Signed on site' });
    expect(prerequisiteStep('signed')).toBeNull();
  });

  it('collision "Resolve" targets (Load → What-if, Certificate → Skills, Document → the Cursus table, Leave → Leave & calendar)', () => {
    const kinds: Record<string, 'load' | 'cert' | 'doc' | 'leave'> = { Load: 'load', Certificate: 'cert', Document: 'doc', Leave: 'leave' };
    for (const c of G.collisionTargets) expect(COLLISION_TARGET[kinds[c.kind]]).toBe(c.screen === 'site' ? c.siteTab : c.screen);
  });

  it('tabs: ?tab= values, unknown → Readiness & go', () => {
    expect(['ready', 'team', 'exec', 'nope', undefined, null].map(siteTabOf)).toEqual(['ready', 'team', 'exec', 'ready', 'ready', 'ready']);
  });
});

describe('late prerequisites (J-15 rule, 10 OQ6)', () => {
  it('pending at J-15 of the need date or later → late; confirmed / signed never late', () => {
    expect(isPrerequisiteLate({ status: 'pending', neededBy: '2026-10-10' }, '2026-09-24')).toBe(false);
    expect(isPrerequisiteLate({ status: 'pending', neededBy: '2026-10-10' }, '2026-09-25')).toBe(true);
    expect(isPrerequisiteLate({ status: 'pending', neededBy: '2026-10-10' }, '2026-10-12')).toBe(true);
    expect(isPrerequisiteLate({ status: 'confirmed', neededBy: '2026-10-10' }, '2026-10-12')).toBe(false);
    expect(isPrerequisiteLate({ status: 'signed', neededBy: '2026-09-01' })).toBe(false);
  });
  it('at the status date (25 Sep 2026) none of the seed prerequisites is late, as in the prototype', () => {
    expect(facts().prerequisites.map((p) => p.late)).toEqual(G.seed.en.prereqs.map((p: any) => p.late));
    // The prototype's list of dates ('12 Oct', '16 Oct') flagged pending rows due then; the rule flags them from J-15.
    expect(isPrerequisiteLate({ status: 'pending', neededBy: '2026-10-12' })).toBe(false);
    expect(isPrerequisiteLate({ status: 'pending', neededBy: '2026-10-12' }, '2026-09-27')).toBe(true);
  });
});

describe('computed literals of the prototype (10 OQ7)', () => {
  it('man-days consumed = headcounts reported from the site start; incidents from Vigie\'s register; rotations of the plan', () => {
    const f = facts();
    const reports = [
      { reportOn: '2026-09-25', headcount: 6, hseIncident: 'none' as const },
      { reportOn: '2026-10-19', headcount: 24, hseIncident: 'incident' as const },
      { reportOn: '2026-10-20', headcount: 22, hseIncident: 'near_miss' as const },
    ];
    expect(manDaysConsumed({ startOn: f.startOn, reports })).toBe(46);
    const g = { ...f, reports, rotation: [{ rotationNo: 1 }] };
    expect(teamKpis(g, 'en').slice(0, 2).map((k) => k.sub)).toEqual(['1 rotation · 44 working days', '46 consumed · site starts 19 Oct 2026']);
    // A-12 (chapter 4): the HSE tile counts what Vigie reports on its registers, not the daily reports' own field.
    expect(execKpis(g).map((k) => [k.value, k.sub]).slice(1, 4)).toEqual([['3', 'Mobile · hours, %, photos, weather'], ['2', '1 on the client'], ['0 incident', '2 permits pending']]);
    const v = { ...g, hse: [...g.hse, { status: 'recorded' as const, kind: 'register', statusText: '2 déclarés' }], clientDecisions: 2 };
    expect(execKpis(v).map((k) => [k.value, k.sub]).slice(3)).toEqual([['2 incidents', '2 permits pending'], ['2', 'Out-of-scope requests → change request']]);
  });
  it('the preparation footnote while the site has not started', () => {
    expect(preparationNote({ startOn: '2026-10-19', doneDays: 0 })).toBe('Site starts 19 Oct — reports so far cover preparation visits.');
    expect(preparationNote({ startOn: '2026-10-19', doneDays: 3 })).toBeNull();
    expect(preparationNote({ startOn: '2026-10-19', doneDays: 0 }, '2026-10-20')).toBeNull();
  });
});

describe('Daily report form (AF.site)', () => {
  const parse = (v: Record<string, string>) => parseDailyReportForm(v, { today: '2026-09-25', parseDate: (s) => parseDateInput(s) });
  it('the prototype form: date, weather, headcount, progress (required), HSE', () => {
    expect(G.form.fields.map((f: any[]) => [f[0], f[1], f[2], f[4] ?? 0])).toEqual([
      ['date', 'Date', 'text', 0], ['weather', 'Weather', 'select', 0], ['headcount', 'Headcount on site', 'number', 0], ['progress', 'Progress', 'textarea', 1], ['incident', 'HSE', 'select', 0],
    ]);
    expect(G.formResult).toBe('Daily report saved');
  });
  it('valid values (EN and FR dates, blank date = today, blank headcount)', () => {
    expect(parse({ date: '24 Sep 2026', weather: 'rain', headcount: '24', progress: ' Bay 3 columns set ', incident: 'near_miss' }))
      .toEqual({ ok: true, value: { date: '2026-09-24', weather: 'rain', headcount: 24, progress: 'Bay 3 columns set', incident: 'near_miss' } });
    expect(parse({ date: '25 sept. 2026', progress: 'x' })).toMatchObject({ ok: true, value: { date: '2026-09-25', weather: 'clear', headcount: null, incident: 'none' } });
    expect(parse({ date: '', progress: 'x' })).toMatchObject({ ok: true, value: { date: '2026-09-25' } });
  });
  it('refuses a blank progress, an unreadable or future date, a bad headcount and unknown codes', () => {
    expect(parse({ progress: '  ' })).toEqual({ ok: false, error: 'Progress is required' });
    expect(parse({ date: '31 Sep 2026', progress: 'x' })).toEqual({ ok: false, error: 'Enter a date such as 25 Sep 2026' });
    expect(parse({ date: '30 Sep 2026', progress: 'x' })).toEqual({ ok: false, error: 'A daily report cannot be dated after today' });
    expect(parse({ headcount: '2.5', progress: 'x' })).toEqual({ ok: false, error: 'Headcount must be a whole number' });
    expect(parse({ headcount: '-1', progress: 'x' })).toEqual({ ok: false, error: 'Headcount must be a whole number' });
    expect(parse({ weather: 'Clear', progress: 'x' })).toEqual({ ok: false, error: 'Invalid request' });
    expect(parse({ incident: 'fire', progress: 'x' })).toEqual({ ok: false, error: 'Invalid request' });
    expect(parse({ progress: 'x'.repeat(2001) })).toEqual({ ok: false, error: 'Progress is too long' });
  });
});
